-- ========================================================
-- LOST & FOUND DBMS - COMPLETE RELATIONAL DATABASE SCHEMA
-- Featuring 260001+ Formatted User IDs (e.g. 260001, 260002, 260003...)
-- With BLOB Image Storage in lost_item and found_item
-- With Primary Keys, Foreign Keys & 50 Entries per Table (400 records total)
-- ========================================================

CREATE DATABASE IF NOT EXISTS lost_and_found_db 
CHARACTER SET utf8mb4 
COLLATE utf8mb4_unicode_ci;

USE lost_and_found_db;

-- Disable Foreign Key checks for clean reset
SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS feedback;
DROP TABLE IF EXISTS claim;
DROP TABLE IF EXISTS notification;
DROP TABLE IF EXISTS item_hand_over;
DROP TABLE IF EXISTS review;
DROP TABLE IF EXISTS item_matching;
DROP TABLE IF EXISTS found_item;
DROP TABLE IF EXISTS lost_item;
DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS location;
SET FOREIGN_KEY_CHECKS = 1;

-- --------------------------------------------------------
-- 1. LOCATION TABLE (Primary Entity)
-- --------------------------------------------------------
CREATE TABLE location (
    location_id INT AUTO_INCREMENT PRIMARY KEY,
    building_name VARCHAR(120) NOT NULL,
    floor_room VARCHAR(80) NOT NULL,
    campus_zone VARCHAR(80) DEFAULT 'Main Campus',
    description VARCHAR(255) NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB AUTO_INCREMENT=1;

-- --------------------------------------------------------
-- 2. USERS TABLE (Primary Entity with 260001+ Meaningful IDs)
-- --------------------------------------------------------
CREATE TABLE users (
    user_id INT AUTO_INCREMENT PRIMARY KEY,
    email VARCHAR(191) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    full_name VARCHAR(120) NOT NULL,
    prn_number VARCHAR(50) NULL UNIQUE,
    role ENUM('student', 'staff', 'admin') NOT NULL DEFAULT 'student',
    department VARCHAR(100) NULL,
    phone VARCHAR(20) NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB AUTO_INCREMENT=260001;

-- --------------------------------------------------------
-- 3. LOST_ITEM TABLE (Foreign Keys -> users, location)
-- Stores images directly as binary BLOB (MEDIUMBLOB)
-- --------------------------------------------------------
CREATE TABLE lost_item (
    lost_id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL,
    location_id INT NULL,
    title VARCHAR(150) NOT NULL,
    category VARCHAR(80) NOT NULL,
    date_lost DATE NOT NULL,
    description TEXT NOT NULL,
    image_data MEDIUMBLOB NULL,
    image_mime VARCHAR(60) DEFAULT 'image/jpeg',
    status VARCHAR(50) DEFAULT 'Searching',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_lost_user FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_lost_location FOREIGN KEY (location_id) REFERENCES location(location_id) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1;

-- --------------------------------------------------------
-- 4. FOUND_ITEM TABLE (Foreign Keys -> users, location)
-- Stores images directly as binary BLOB (MEDIUMBLOB)
-- --------------------------------------------------------
CREATE TABLE found_item (
    found_id INT AUTO_INCREMENT PRIMARY KEY,
    finder_user_id INT NULL,
    location_id INT NULL,
    title VARCHAR(150) NOT NULL,
    category VARCHAR(80) NOT NULL,
    date_found DATE NOT NULL,
    description TEXT NOT NULL,
    image_data MEDIUMBLOB NULL,
    image_mime VARCHAR(60) DEFAULT 'image/jpeg',
    status VARCHAR(50) DEFAULT 'In Safekeeping',
    safekeeping_counter VARCHAR(50) DEFAULT 'Desk Counter 2',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_found_finder FOREIGN KEY (finder_user_id) REFERENCES users(user_id) ON DELETE SET NULL,
    CONSTRAINT fk_found_location FOREIGN KEY (location_id) REFERENCES location(location_id) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1;

-- --------------------------------------------------------
-- 5. ITEM_MATCHING TABLE (Foreign Keys -> lost_item, found_item)
-- --------------------------------------------------------
CREATE TABLE item_matching (
    match_id INT AUTO_INCREMENT PRIMARY KEY,
    lost_id INT NOT NULL,
    found_id INT NOT NULL,
    similarity_score DECIMAL(5,2) NOT NULL,
    vision_score DECIMAL(5,2) NULL,
    text_score DECIMAL(5,2) NULL,
    match_status ENUM('Candidate', 'Confirmed', 'Dismissed') DEFAULT 'Candidate',
    matched_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_match_lost FOREIGN KEY (lost_id) REFERENCES lost_item(lost_id) ON DELETE CASCADE,
    CONSTRAINT fk_match_found FOREIGN KEY (found_id) REFERENCES found_item(found_id) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1;

-- --------------------------------------------------------
-- 6. REVIEW TABLE (Foreign Keys -> found_item, users)
-- --------------------------------------------------------
CREATE TABLE review (
    review_id INT AUTO_INCREMENT PRIMARY KEY,
    found_id INT NOT NULL,
    claimant_user_id INT NOT NULL,
    reviewer_admin_id INT NULL,
    proof_description TEXT NOT NULL,
    proof_image LONGTEXT NULL,
    verification_status VARCHAR(50) DEFAULT 'Pending Review',
    rejection_reason VARCHAR(255) NULL,
    reviewed_at TIMESTAMP NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_review_found FOREIGN KEY (found_id) REFERENCES found_item(found_id) ON DELETE CASCADE,
    CONSTRAINT fk_review_claimant FOREIGN KEY (claimant_user_id) REFERENCES users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_review_admin FOREIGN KEY (reviewer_admin_id) REFERENCES users(user_id) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1;

-- --------------------------------------------------------
-- 7. ITEM_HAND_OVER TABLE (Foreign Keys -> review, found_item, users)
-- --------------------------------------------------------
CREATE TABLE item_hand_over (
    handover_id INT AUTO_INCREMENT PRIMARY KEY,
    review_id INT NOT NULL UNIQUE,
    found_id INT NOT NULL,
    claimant_user_id INT NOT NULL,
    security_officer_id INT NULL,
    token_code VARCHAR(50) NOT NULL UNIQUE,
    counter_number VARCHAR(30) DEFAULT 'Counter 2',
    handover_status VARCHAR(50) DEFAULT 'Pass Issued',
    handover_timestamp TIMESTAMP NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_handover_review FOREIGN KEY (review_id) REFERENCES review(review_id) ON DELETE CASCADE,
    CONSTRAINT fk_handover_found FOREIGN KEY (found_id) REFERENCES found_item(found_id) ON DELETE CASCADE,
    CONSTRAINT fk_handover_claimant FOREIGN KEY (claimant_user_id) REFERENCES users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_handover_officer FOREIGN KEY (security_officer_id) REFERENCES users(user_id) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1;

-- --------------------------------------------------------
-- 8. NOTIFICATION TABLE (Foreign Key -> users)
-- --------------------------------------------------------
CREATE TABLE notification (
    notification_id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL,
    title VARCHAR(150) NOT NULL,
    message TEXT NOT NULL,
    type VARCHAR(50) DEFAULT 'system',
    is_read BOOLEAN DEFAULT FALSE,
    related_item_id INT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_notif_user FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1;











-- --------------------------------------------------------
-- 9. CLAIM TABLE (Nexus Table Connected to ALL Other Tables)
-- Links: users, found_item, lost_item, item_matching, location, review, item_hand_over, notification
-- --------------------------------------------------------
CREATE TABLE IF NOT EXISTS claim (
    claim_id INT AUTO_INCREMENT PRIMARY KEY,
    claim_code VARCHAR(50) NOT NULL UNIQUE,
    claimant_user_id INT NOT NULL,
    found_id INT NOT NULL,
    lost_id INT NULL,
    match_id INT NULL,
    location_id INT NULL,
    review_id INT NULL,
    handover_id INT NULL,
    notification_id INT NULL,
    proof_description TEXT NOT NULL,
    proof_image LONGTEXT NULL,
    claim_status VARCHAR(50) DEFAULT 'Pending Review',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_claim_user FOREIGN KEY (claimant_user_id) REFERENCES users(user_id) ON DELETE CASCADE,
    CONSTRAINT fk_claim_found FOREIGN KEY (found_id) REFERENCES found_item(found_id) ON DELETE CASCADE,
    CONSTRAINT fk_claim_lost FOREIGN KEY (lost_id) REFERENCES lost_item(lost_id) ON DELETE SET NULL,
    CONSTRAINT fk_claim_match FOREIGN KEY (match_id) REFERENCES item_matching(match_id) ON DELETE SET NULL,
    CONSTRAINT fk_claim_location FOREIGN KEY (location_id) REFERENCES location(location_id) ON DELETE SET NULL,
    CONSTRAINT fk_claim_review FOREIGN KEY (review_id) REFERENCES review(review_id) ON DELETE SET NULL,
    CONSTRAINT fk_claim_handover FOREIGN KEY (handover_id) REFERENCES item_hand_over(handover_id) ON DELETE SET NULL,
    CONSTRAINT fk_claim_notification FOREIGN KEY (notification_id) REFERENCES notification(notification_id) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1;

